Here is a simple Python script using Flask to create a screensharing endpoint:

```
from flask import Flask, request, jsonify
import uuid
import os

app = Flask(__name__)

# Create a dictionary to store the active screensharing sessions
session_dict = {}

@app.route('/screenshare', methods=['POST'])
def start_session():
    url = request.get_json()['url']
    session_id = str(uuid.uuid4())
    session_dict[session_id] = url
    return jsonify({'session_id': session_id})

@app.route('/get/share', methods=['GET'])
def get_session_id():
    session_id = request.args.get('session_id')
    if session_id in session_dict:
        return jsonify({'url': session_dict[session_id]})
    else:
        return jsonify({'error': 'Invalid session id'}), 404

@app.route('/stop', methods=['DELETE'])
def stop_session():
    session_id = request.get_json()['session_id']
    if session_id in session_dict:
        del session_dict[session_id]
        return jsonify({'message': 'Session stopped'})
    else:
        return jsonify({'error': 'Invalid session id'}), 404

if __name__ == '__main__':
    app.run(debug=True)
```

