Here is a simple JavaScript applet that demonstrates a pendulum simulation:
```
// Define the physical constants
const G = 9.8; // gravity (m/s^2)
const TAU = 0.5; // period of a pendulum (seconds)

// Define the initial conditions
let theta = 45; // initial angle (degrees)
let omega = 0; // initial angular velocity (rad/s)
let dt = 0.01; // time step (seconds)

// Create the canvas element
const canvas = document.getElementById('pendulum');
const ctx = canvas.getContext('2d');

// Define the pendulum function
function pendulum() {
  // Calculate the angular acceleration
  const domega = -G/TAU * Math.sin(theta);

  // Update the angular velocity and angle
  omega += domega * dt;
  theta += omega * dt;

  // Draw the pendulum
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width/2, canvas.height/2, 20, theta, Math.PI/2);
  ctx.stroke();

  // Update the request animation frame
  requestAnimationFrame(pendulum);
}

// Start the pendulum simulation
pendulum();

// Add an event listener for the button
document.getElementById('release').addEventListener('click', function() {
  // Set the initial conditions
  theta = Math.radians(document.getElementById('theta').value);
  omega = 0;

  // Start the pendulum simulation
  pendulum();
});
```
