Here is an AWS Lambda function in Go that deletes EBS Snapshots based on the specified tag and retention policies:
```go
package main

import (
	"context"
	"fmt"
	"log"

	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS Snapshots with the "backup_type" tag
	params := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup_type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	}

	resp, err := ec2Svc.DescribeSnapshots(params)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Process each snapshot
	for _, snap := range resp.Snapshots {
		tagValue := snap.Tags[0].Value
		log.Println("Processing snapshot:", snap.SnapshotId, "with tag", tagValue)

		// Determine the retention policy based on the tag value
		switch *tagValue {
		case "monthly":
			keepCount := 14
		case "daily":
			keepCount := 10
		case "weekly":
			keepCount := 4
		case "yearly":
			keepCount := 1
		default:
			log.Println("Unknown tag value:", tagValue)
			continue
		}

		// Get the list of snapshots for this tag value
		params = &ec2.DescribeSnapshotsInput{
			Filters: []*ec2.Filter{
				{
					Name: aws.String("tag:backup_type"),
					Values: []*string{
						aws.String(tagValue),
					},
				},
			},
		}

		resp, err = ec2Svc.DescribeSnapshots(params)
		if err != nil {
			log.Println(err)
			return nil, err
		}

		// Find the oldest snapshots to delete
		var toDelete []*ec2.Snapshot
		for _, snap := range resp.Snapshots {
			if toDelete == nil {
				toDelete = []*ec2.Snapshot{snap}
			} else {
				removeSnap := false
				for _, deleteSnap := range toDelete {
					if snap.Volumes[0].VolumeId < deleteSnap.Volumes[0].VolumeId {
						removeSnap = true
						break
					}
				}
				if removeSnap {
					toDelete = append(toDelete, snap)
				} else {
					toDelete = toDelete[:len(toDelete)-1]
				}
			}
		}

		// Delete the oldest snapshots
		for _, snap := range toDelete {
			log.Println("Deleting snapshot:", snap.SnapshotId)
			ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: aws.String(snap.SnapshotId),
			})
		}
	}

	return nil, nil
}

func main() {
	lambda.Start(handler)
}
```
